    const before = s.slice(Math.max(0, off - 48), off);
    const after = s.slice(off + m.length, off + m.length + 24);
    const aYear = shouldReadAsYear(na, before, " to ") || (na >= 1500 && na <= 2099);
    const bYear = shouldReadAsYear(nb, " to ", after) || (nb >= 1500 && nb <= 2099);
    if (aYear && bYear) return `${yearToWords(na)} to ${yearToWords(nb)}`;
