const ONSETS = [
  "ky", "gy", "sh", "ch", "ts", "ny", "hy", "by", "py", "my", "ry",
  "k", "g", "s", "z", "t", "d", "n", "h", "b", "p", "m", "r", "w", "y", "j", "f", "v", "c",
];

function normalizeRomajiInput(word) {
  let s = String(word).normalize("NFC").toLowerCase();
  s = s
    .replace(/ā/g, "aa")
    .replace(/ī/g, "ii")
    .replace(/ū/g, "uu")
    .replace(/ē/g, "ee")
    .replace(/ō/g, "oo");
  return s;
}

/**
 * Parse Hepburn romaji into mora list, or null.
 */
function parseRomaji(word) {
  const s = normalizeRomajiInput(word);
  if (!s || !/^[a-z']+$/.test(s)) return null;

  const morae = [];
  let i = 0;
  while (i < s.length) {
    // n' before vowel/y
    if (s[i] === "n" && s[i + 1] === "'") {
      morae.push("n");
      i += 2;
      continue;
    }
    // moraic n before consonant or end (not before vowel/y)
    if (s[i] === "n") {
      const next = s[i + 1];
      if (!next || (!VOWELS.has(next) && next !== "y")) {
        morae.push("n");
        i += 1;
        continue;
      }
    }

    // sokuon: kk, pp, tt, ss, …
    if (
      i + 1 < s.length &&
      s[i] === s[i + 1] &&
      !VOWELS.has(s[i]) &&
      s[i] !== "n"
    ) {
      morae.push("っ");
      i += 1;
      continue;
    }
    if (s.startsWith("tch", i)) {
      morae.push("っ");
      i += 1;
      continue;
    }

    let onset = "";
    for (const o of ONSETS) {
      if (!s.startsWith(o, i)) continue;
      const after = i + o.length;
      if (after < s.length && VOWELS.has(s[after])) {
        onset = o;
        break;
      }
    }

    let vowelStart;
    if (onset) {
      vowelStart = i + onset.length;
    } else if (VOWELS.has(s[i])) {
      vowelStart = i;
      onset = "";
    } else {
      return null;
    }

    let vowel = s[vowelStart];
    let vlen = 1;
    const two = s.slice(vowelStart, vowelStart + 2);
    if (["aa", "ii", "uu", "ee", "oo", "ou"].includes(two)) {
      vowel = two;
      vlen = 2;
    }

    morae.push(onset + vowel);
    i = vowelStart + vlen;
  }

  return morae.length ? morae : null;
}

function isValidRomaji(word) {
  const m = parseRomaji(word);
  return Array.isArray(m) && m.length >= 2;
}

const V_IPA = {
  a: "ɑ", i: "i", u: "ɯ", e: "e", o: "o",
  aa: "ɑː", ii: "iː", uu: "ɯː", ee: "eː", oo: "oː", ou: "oː",
};

const ONSET_IPA = {
  // Japanese /r/ as flap ɾ — English ɹ after /o/ becomes "ar" (Takamori→Takamari).
  k: "k", g: "ɡ", s: "s", z: "z", t: "t", d: "d", n: "n", h: "h", b: "b", p: "p",
  m: "m", r: "ɾ", w: "w", y: "j", j: "ʤ", f: "f", v: "v", c: "k",
  ky: "kj", gy: "ɡj", sh: "ʃ", ch: "ʧ", ts: "ts", ny: "nj", hy: "hj",
  by: "bj", py: "pj", my: "mj", ry: "ɾj",
};

/**
 * Split a mora into onset phones + vowel phones (no stress marks).
 * @returns {{ onset: string, vowel: string }|null}
 */
function moraParts(mora) {
  if (mora === "n") return { onset: "n", vowel: "" };
  if (mora === "っ") return { onset: "ʔ", vowel: "" };
  for (const o of ONSETS) {
    if (mora.startsWith(o) && mora.length > o.length) {
      const v = mora.slice(o.length);
      if (V_IPA[v]) return { onset: ONSET_IPA[o] || o, vowel: V_IPA[v] };
    }
  }
  if (V_IPA[mora]) return { onset: "", vowel: V_IPA[mora] };
  return null;
}

/**
 * Stress on penultimate mora (Takahashi / Nakatsuka / Kawasaki style).
 * Stress mark is placed AFTER the onset consonant(s), before the vowel, so the
 * name never begins with ˈ/ˌ (Kokoro otherwise prepends a stray vowel:
 * Nakatsuka→Anakatsuka, Yoko→Ioko, Koki→Akoki).
 * No leading secondary stress.
 */
function romajiToIpa(word) {
  const morae = parseRomaji(word);
  if (!morae) return null;
  const parts = [];
  for (const m of morae) {
    const p = moraParts(m);
    if (p == null) return null;
    parts.push(p);
  }
  const stressable = [];
  for (let i = 0; i < morae.length; i++) {
    if (morae[i] !== "っ") stressable.push(i);
  }
  const stressIdx =
    stressable.length >= 2 ? stressable[stressable.length - 2] : stressable[0] ?? 0;
  let out = "";
  for (let i = 0; i < parts.length; i++) {
    const { onset, vowel } = parts[i];
    if (i === stressIdx && vowel) {
      if (i === 0) {
        // First mora: keep a leading consonant/glide (jˈoko not ˈjoko→Ioko).
        out += onset + "ˈ" + vowel;
      } else {
        // Later mora: standard IPA stress before the syllable (nɑkɑˈtsɯkɑ).
        out += "ˈ" + onset + vowel;
      }
    } else {
      out += onset + vowel;
    }
  }
  return sanitizeIpa(out);
}

/**
 * @param {string} word
 * @param {{ force?: boolean, english?: Set<string>, allow?: Set<string> }} opts
 */
function isJapaneseRomajiWord(word, opts = {}) {
  const allow = opts.allow || loadAllowlist();
  const english = opts.english || loadEnglishDict();
  const raw = String(word);
  const lower = raw.toLowerCase();

  if (allow.has(lower)) return false;
  const morae = parseRomaji(raw);
  if (!morae || morae.length < 2) return false;
  if (morae.length < 3 && !opts.force && !/^[A-Z]/.test(raw)) return false;
  if (!opts.force && english.has(lower)) return false;

  if (/^[A-Z][a-z]+$/.test(raw) || /^[A-Z]{3,}$/.test(raw)) {
    if (opts.force) return true;
    if (english.has(lower) && morae.length < 4) return false;
    return true;
  }
  if (opts.force) return !english.has(lower);
  if (morae.length >= 4 && !english.has(lower)) return true;
  return false;
}

function applyRomaji(text, opts = {}) {
  const ipaPlaceholders = opts.ipaPlaceholders || new Map();
  const detected = [];
  let n = opts.startIndex || 0;

  const out = String(text).replace(/\b[A-Za-z][A-Za-z']*\b/g, (tok) => {
    // Skip IPA placeholders
    if (/^A\d+$/.test(tok) || /^R\d+$/.test(tok)) return tok;
    if (!isJapaneseRomajiWord(tok, opts)) return tok;
    const ipa = romajiToIpa(tok);
    if (!ipa) return tok;
    const key = `⟦R${n++}⟧`;
    // Kokoro treats an injected internal stress before a Japanese onset as a
    // vowel boundary. Names are more stable without synthetic stress marks.
    ipaPlaceholders.set(key, { kind: "ipa", value: ipa.replace(/[ˈˌ]/g, "") });
    detected.push(tok);
    return key;
  });

  return { text: out, ipaPlaceholders, detected, nextIndex: n };
}

function getEnglishDict() {
  return loadEnglishDict();
}

function getAllowlist() {
  return loadAllowlist();
}

/** Sample English words that parse as romaji but are NOT detected as Japanese. */
function englishWordsNotDetected(sampleSize = 100) {
  const english = loadEnglishDict();
  const out = [];
  for (const w of english) {
    if (out.length >= sampleSize) break;
    const morae = parseRomaji(w);
    if (!morae || morae.length < 2) continue;
    const titled = w[0].toUpperCase() + w.slice(1);
    if (!isJapaneseRomajiWord(w) && !isJapaneseRomajiWord(titled)) {
      out.push(w);
    }
  }
  return out;
}


/* ---- rules/acronyms.mjs ---- */
/**
 * Acronym handling (rule 2).
 * Word-acronyms read as words; others spelled letter-by-letter.
 * Possessive / plural forms (METI's, IPOs, SMEs, US's) keep the base spelled
 * and append a suffix phone so leftover 's is never fed to espeak as a word.
 * ALLCAPS Japanese names (MEGUMI) deferred to romaji rule.
 */


/** Curated word-acronyms (matched case-insensitively). */
const WORD_ACRONYMS = new Set([
  "NASA", "NATO", "OPEC", "ASEAN", "UNESCO", "UNICEF", "NVIDIA", "SOFTBANK",
  "COVID", "NAFTA", "FIFA", "UEFA", "LASER", "RADAR", "SCUBA", "NASCAR",
  "UNHCR", "OECD", "INTERPOL", "CISCO", "SONY", "COSTCO", "CANON",
]);

const LETTER_IPA = {
  A: "ˈeɪ", B: "bˈiː", C: "sˈiː", D: "dˈiː", E: "ˈiː", F: "ˈɛf", G: "ʤˈiː",
  H: "ˈeɪʧ", I: "ˈaɪ", J: "ʤˈeɪ", K: "kˈeɪ", L: "ˈɛl", M: "ˈɛm", N: "ˈɛn",
  O: "ˈoʊ", P: "pˈiː", Q: "kjˈuː", R: "ˈɑːɹ", S: "ˈɛs", T: "tˈiː", U: "jˈuː",
  V: "vˈiː", W: "dˈʌbəljˌuː", X: "ˈɛks", Y: "wˈaɪ", Z: "zˈiː",
};

/** Possessive / plural suffix phones after spelled letters. */
const SUFFIX_IPA = {
  possessive: "z", // METI's, US's
  plural_s: "z", // IPOs, SMEs
};

/** Bases that take a plural -s (IPOs, SMEs). Avoid peeling USES→USE+s. */
const PLURAL_ACRONYMS = new Set([
  "IPO", "SME", "CEO", "CFO", "CTO", "CMO", "API", "GPU", "CPU", "LLM",
  "ETF", "NGO", "GDP", "KPI", "OKR", "RSU", "SLA", "SDK", "IDE", "PDF",
]);

function spellLettersIpa(token) {
  const letters = String(token).replace(/[^A-Za-z]/g, "").toUpperCase().split("");
  return letters.map((L) => LETTER_IPA[L] || "").filter(Boolean).join(" ");
}

function isAllCapsToken(tok) {
  return /^[A-Z]{2,}(?:&[A-Z]+)?$/.test(tok);
}

function isWordAcronym(tok) {
  if (/^softbank$/i.test(tok)) return true;
  if (/^nvidia$/i.test(tok)) return true;
  const u = String(tok).replace(/&/g, "").toUpperCase();
  return WORD_ACRONYMS.has(u);
}

/**
 * Split a raw token into acronym base + optional possessive/plural suffix.
 * @returns {{ base: string, suffix: "possessive"|"plural_s"|"plural_es"|null }|null}
 */
function splitAcronymAffix(tok) {
  const t = String(tok);
  let m = t.match(/^([A-Z]{2,}(?:&[A-Z]+)?)(['’]s)$/);
  if (m) return { base: m[1], suffix: "possessive" };
  // IPOs / SMEs — plural -s only for known pluralizable bases (not USES→USE+s).
  m = t.match(/^([A-Z]{2,}(?:&[A-Z]+)?)(s)$/);
  if (m && PLURAL_ACRONYMS.has(m[1])) {
    return { base: m[1], suffix: "plural_s" };
  }
  if (/^[A-Z]{2,}(?:&[A-Z]+)?$/.test(t)) return { base: t, suffix: null };
  return null;
}

/**
 * @returns {"word"|"spell"|"romaji"|null}
 */
function classifyAcronym(tok, opts = {}) {
  const t = String(tok);
  if (/^M&A$/i.test(t)) return "spell";
  const split = splitAcronymAffix(t);
  const base = split ? split.base : t;
  if (isWordAcronym(base) && !(split && split.suffix)) return "word";
  if (isWordAcronym(base) && split && split.suffix) {
    // NASA's → still word + suffix handled by apply; classify as word for base.
    return "word";
  }
  // ALLCAPS Japanese names need ≥3 morae (MEGUMI); METI/LNG/IPO stay spelled.
  if (
    isAllCapsToken(base) &&
    base.replace(/&/g, "").length >= 5 &&
    isJapaneseRomajiWord(base, { ...opts, force: true })
  ) {
    return "romaji";
  }
  if (isAllCapsToken(base) || (split && isAllCapsToken(base))) return "spell";
  return null;
}

function ipaForAcronymToken(tok, opts = {}) {
  const split = splitAcronymAffix(tok) || { base: tok, suffix: null };
  const kind = classifyAcronym(split.base, opts);
  if (kind === "romaji") return { kind: "romaji", base: split.base, suffix: split.suffix };
  if (kind === "word") {
    return { kind: "word", base: split.base, suffix: split.suffix };
  }
  if (kind === "spell" || (split.suffix && isAllCapsToken(split.base))) {
    let ipa = spellLettersIpa(split.base);
    if (split.suffix && SUFFIX_IPA[split.suffix]) {
      ipa = `${ipa}${SUFFIX_IPA[split.suffix]}`;
    }
    return { kind: "spell", ipa, base: split.base, suffix: split.suffix };
  }
  return null;
}

/**
 * Replace acronyms in text. Spelled forms → IPA placeholders ⟦A#⟧.
 * @returns {{ text: string, ipaPlaceholders: Map<string,string>, stats: {spell:number,word:number,romaji:number} }}
 */
function applyAcronyms(text, opts = {}) {
  const ipaPlaceholders = opts.ipaPlaceholders || new Map();
  const stats = { spell: 0, word: 0, romaji: 0 };
  let n = opts.startIndex || 0;

  // Multi-word: SK hynix / SK Hynix
  let s = String(text).replace(/\bSK\s+[Hh]ynix\b/g, () => {
    stats.spell++;
    const key = `⟦A${n++}⟧`;
    ipaPlaceholders.set(key, { kind: "ipa", value: `${LETTER_IPA.S} ${LETTER_IPA.K} hˈaɪnɪks` });
    return key;
  });

  s = s.replace(/\bM&A\b/gi, () => {
    stats.spell++;
    const key = `⟦A${n++}⟧`;
    ipaPlaceholders.set(key, { kind: "ipa", value: `${LETTER_IPA.M} ænd ${LETTER_IPA.A}` });
    return key;
  });

  // Possessive / plural / bare ALLCAPS (METI's, IPOs, SMEs, US's, METI)
  s = s.replace(/\b[A-Z]{2,}(?:&[A-Z]+)?(?:['’]s|s)?\b/g, (tok) => {
    const split = splitAcronymAffix(tok);
    if (!split && !/^[A-Z]{2,}(?:&[A-Z]+)?$/.test(tok)) return tok;
    const info = ipaForAcronymToken(tok, opts);
    if (!info) return tok;
    if (info.kind === "romaji") {
      stats.romaji++;
      return split ? split.base : tok;
    }
    if (info.kind === "word") {
      stats.word++;
      if (info.suffix === "possessive") return `${info.base}'s`;
      if (info.suffix === "plural_s") return `${info.base}s`;
      return info.base;
    }
    if (info.kind === "spell") {
      stats.spell++;
      const key = `⟦A${n++}⟧`;
      ipaPlaceholders.set(key, { kind: "ipa", value: info.ipa });
      return key;
    }
    return tok;
  });

  // SoftBank / NVIDIA title-ish
  s = s.replace(/\bSoftBank\b/g, (tok) => {
    stats.word++;
    return tok;
  });
  s = s.replace(/\bNVIDIA\b/gi, (tok) => {
    stats.word++;
    return "NVIDIA";
  });

  return { text: s, ipaPlaceholders, stats, nextIndex: n };
}

applyAcronyms;


/* ---- rules/phonemize.mjs ---- */
/**
 * Kokoro-compatible phonemize.
 *
 * Mirrors kokoro-js@1.2.1 internal `phonemize` (dist/kokoro.js async function m):
 *   1. optional text norm (we usually pass norm=false; our rules/normalize handles it)
 *   2. phonemizer package (espeak-ng WASM) with en-us / en
 *  3. post-process: kokoro→kokoɹo, ʲ→j, r→ɹ, x→k, ɬ→l, ninety, etc.
 *
 * Node:  import { phonemize as espeakPhonemize } from "https://cdn.jsdelivr.net/npm/phonemizer@1.2.1/+esm";
 * Browser (via build): import { phonemize as espeakPhonemize } from
 *   "https://cdn.jsdelivr.net/npm/phonemizer@1.2.1/+esm"
 * (kokoro-js@1.2.1 pins phonemizer@^1.2.1; public CDN surface is phonemizer, not
 *  an exported phonemize from kokoro-js/+esm which only exports KokoroTTS.)
 */


// Apostrophes stay inside words so espeak can pronounce contractions and
// possessives (can't, there's, Iran's) as lexical forms.
const PUNCT_CLUSTER = /([;:,.!?¡¿—…"«»""(){}[\]]+)/g;

function splitKeepPunct(text) {
  const parts = [];
  let last = 0;
  for (const m of text.matchAll(PUNCT_CLUSTER)) {
    if (m.index > last) parts.push({ match: false, text: text.slice(last, m.index) });
    if (m[0].length) parts.push({ match: true, text: m[0] });
    last = m.index + m[0].length;
  }
  if (last < text.length) parts.push({ match: false, text: text.slice(last) });
  return parts;
}

/** Post-process identical to kokoro-js 1.2.1. */
function postprocessKokoro(phonemes, language = "a") {
  let i = String(phonemes)
    .replace(/kəkˈoːɹoʊ/g, "kˈoʊkəɹoʊ")
    .replace(/kəkˈɔːɹəʊ/g, "kˈəʊkəɹəʊ")
    .replace(/ʲ/g, "j")
    .replace(/r/g, "ɹ")
    .replace(/x/g, "k")
    .replace(/ɬ/g, "l")
    .replace(/(?<=[a-zɹː])(?=hˈʌndɹɪd)/g, " ")
    .replace(/ z(?=[;:,.!?¡¿—…"«»"" ]|$)/g, "z");
  if (language === "a") {
    i = i.replace(/(?<=nˈaɪn)ti(?!ː)/g, "di");
  }
  return i.trim();
}

const _cache = new Map();

/**
 * @param {string} text
 * @param {"a"|"b"} language  a=American (am_michael), b=British
 * @param {boolean} norm  kokoro built-in norm; keep false when using rules/normalize
 * @returns {Promise<string>}
 */
async function phonemize(text, language = "a", norm = false) {
  let e = String(text ?? "");
  if (!e.trim()) return "";
  const cacheKey = `${language}|${norm ? 1 : 0}|${e}`;
  if (_cache.has(cacheKey)) return _cache.get(cacheKey);

  // Minimal safety norm if requested (subset; full path is rules/normalize)
  if (norm) {
    e = e
      .replace(/[‘’]/g, "'")
      .replace(/[“”]/g, '"')
      .replace(/\s+/g, " ")
      .trim();
  }
  const lang = language === "a" ? "en-us" : "en";
  const parts = splitKeepPunct(e);
  const pieces = await Promise.all(
    parts.map(async ({ match, text: piece }) => {
      if (match) return piece;
      if (!piece.trim()) return piece;
      const arr = await espeakPhonemize(piece, lang);
      return Array.isArray(arr) ? arr.join(" ") : String(arr);
    }),
  );
  const out = postprocessKokoro(pieces.join(""), language);
  _cache.set(cacheKey, out);
  return out;
}



/* ---- rules/chunk.mjs ---- */
/**
 * Chunking for Kokoro: first chunk 8–12 words; later pack to 60–160 phoneme
 * tokens (hard max 200). Prefer sentence / clause / comma / conjunction splits.
 * Never split inside a number, a name, or "born YEAR".
 */


/** Soft target / hard cap on phoneme character tokens per chunk. */
const CHUNK_TARGET_MIN = 60;
const CHUNK_TARGET_MAX = 160;
const CHUNK_HARD_MAX = 200;

const SENTENCE_END = /[.!?…]["»”]?$/;
const CLAUSE_END = /[;:]["»”]?$/;
const COMMA_END = /,$/;
const CONJ = /^(and|or|but|so|yet|nor)$/i;

function wordCount(s) {
  return String(s).trim().split(/\s+/).filter(Boolean).length;
}

function phonemeTokenCount(phonemes) {
  return [...String(phonemes || "")].length;
}

/**
 * Match kokoro-js phonemize punctuation spacing: no spaces around ,;:.!?()…
 * and collapse repeated commas.
 */
function normalizePhonemePunct(phonemes) {
  let s = String(phonemes ?? "");
  s = s.replace(/,{2,}/g, ",");
  s = s.replace(/\s*([,;:.!?…—])\s*/g, "$1");
  s = s.replace(/\s*([()])\s*/g, "$1");
  s = s.replace(/\s+/g, " ").trim();
  return s;
}

/**
 * Protect spans that must not be split: numbers, "born/died/circa YEAR", names.
 */
function protectSpans(text) {
  const spans = [];
  const protect = (m) => {
    const i = spans.length;
    spans.push(m);
    return `⟦N${i}⟧`;
  };
  let s = String(text);
  s = s.replace(/\b(?:born|died|circa)\s+\S+/gi, protect);
  // Multi-word / hyphenated Proper Names (An Yong-hak, Nakatsuka Ippekiro)
  s = s.replace(
    /\b[A-Z][A-Za-z]*(?:-[A-Za-z]+)+(?:\s+[A-Z][A-Za-z]*(?:-[A-Za-z]+)*)*\b/g,
    protect,
  );
  s = s.replace(
    /\b[A-Z][a-z]+(?:\s+[A-Z][A-Za-z]*(?:-[A-Za-z]+)*)+\b/g,
    protect,
  );
  s = s.replace(/\b[A-Z]{2,}\b/g, protect); // MEGUMI, US, METI
  s = s.replace(/\b\d{1,3}(?:,\d{3})+(?:\.\d+)?\b/g, protect);
  s = s.replace(/\b\d+\.\d+\b/g, protect);
  s = s.replace(/\b\d+\b/g, protect);

  // normalize() expands numbers before chunking. Keep the resulting numeric
  // phrase, its unit/currency, and numeric ranges together as one word-level
  // chunk so packing cannot create a semantic boundary in the phrase.
  const numberWord =
    "(?:zero|one|two|three|four|five|six|seven|eight|nine|ten|eleven|twelve|" +
    "thirteen|fourteen|fifteen|sixteen|seventeen|eighteen|nineteen|twenty|" +
    "thirty|forty|fifty|sixty|seventy|eighty|ninety|hundred|thousand|million|" +
    "billion|trillion|point|oh)(?:[- ](?:zero|one|two|three|four|five|six|" +
    "seven|eight|nine|ten|eleven|twelve|thirteen|fourteen|fifteen|sixteen|" +
    "seventeen|eighteen|nineteen|twenty|thirty|forty|fifty|sixty|seventy|" +
    "eighty|ninety|hundred|thousand|million|billion|trillion|point|oh))*";
  const unit =
    "(?:percent|percentage points?|basis points?|yen|dollars?|euros?|pounds?|" +
    "tons?|kilograms?|kilometers?|kilowatt hours?|megawatts?|gigawatts?|" +
    "kilowatts?|degrees Celsius|square meters?)";
  s = s.replace(
    new RegExp(`\\b${numberWord}(?:\\s+to\\s+${numberWord})?\\s+${unit}\\b`, "gi"),
    protect,
  );
  s = s.replace(new RegExp(`\\b${numberWord}\\s+to\\s+${numberWord}\\b`, "gi"), protect);
  return { masked: s, spans };
}

function unmask(s, spans) {
  return s.replace(/⟦N(\d+)⟧/g, (_, i) => spans[Number(i)]);
}

function boundaryScore(word) {
  if (SENTENCE_END.test(word)) return 4;
  if (CLAUSE_END.test(word)) return 3;
  if (COMMA_END.test(word)) return 2;
  return 0;
}

/**
 * Split normalized text into word-level chunks (text still orthographic).
 * laterMax defaults low so phoneme packing stays near 60–160 tokens.
 * @returns {string[]}
 */
function chunkText(text, opts = {}) {
  const firstMin = opts.firstMin ?? 8;
  const firstMax = opts.firstMax ?? 12;
  // ~10–14 orthographic words ≈ 60–160 phoneme tokens after year shortening
  const laterMax = opts.laterMax ?? 14;
  const laterMin = opts.laterMin ?? 4;
  const s = String(text).trim();
  if (!s) return [];

  const { masked, spans } = protectSpans(s);
  const words = masked.split(/\s+/).filter(Boolean);
  if (!words.length) return [];

  const chunks = [];
  let i = 0;

  if (words.length <= firstMax) {
    return [unmask(words.join(" "), spans)];
  }
  let firstLen = Math.min(firstMax, Math.max(firstMin, Math.min(12, words.length)));
  let firstEnd = firstLen;
  for (let j = firstMin; j <= firstLen; j++) {
    if (boundaryScore(words[j - 1]) >= 2) {
      firstEnd = j;
      break;
    }
  }
  // Prefer ending before a conjunction when inside the first window
  for (let j = firstMin; j < firstLen; j++) {
    if (CONJ.test(words[j]) && j >= firstMin) {
      firstEnd = j;
      break;
    }
  }
  chunks.push(unmask(words.slice(0, firstEnd).join(" "), spans));
  i = firstEnd;

  while (i < words.length) {
    let end = Math.min(i + laterMax, words.length);
    let splitAt = end;
    // Prefer the latest (rightmost) high-score boundary inside the window so
    // chunks pack toward the 60–160 token target instead of fragmenting early.
    let best = { at: end, score: 0 };

    const trySplit = (at, score) => {
      if (at < i + laterMin && at !== words.length) return;
      if (at > end) return;
      if (score > best.score || (score === best.score && at > best.at)) {
        best = { at, score };
      }
    };

    // 1) sentence 2) ; : 3) comma / paren-tail 4) before conjunction 5) word boundary
    for (let j = end; j > i; j--) {
      const sc = boundaryScore(words[j - 1]);
      if (sc) trySplit(j, sc);
    }
    for (let j = Math.min(end, words.length - 1); j > i + laterMin - 1; j--) {
      if (CONJ.test(words[j])) trySplit(j, 1);
    }
    splitAt = best.score > 0 ? best.at : end;

    chunks.push(unmask(words.slice(i, splitAt).join(" "), spans));
    i = splitAt;
  }

  return chunks.map((c) => c.trim()).filter(Boolean);
}

/**
 * Pack / split phoneme strings to CHUNK_HARD_MAX (prefer ≤ CHUNK_TARGET_MAX).
 */
function chunkPhonemes(phonemes, opts = {}) {
  const hardMax = opts.hardMax ?? CHUNK_HARD_MAX;
  const targetMax = opts.targetMax ?? CHUNK_TARGET_MAX;
  const p = normalizePhonemePunct(phonemes);
  if (!p) return [];
  if (phonemeTokenCount(p) <= targetMax) {
    if (phonemeTokenCount(p) > MAX_PHONEME_CHARS) assertPhonemeLimit(p);
    return [p];
  }

  // Split on pause punctuation (already unspaced after normalize)
  const parts = p.split(/(?<=[;:,.!?…—)])|(?=[(])/).filter((x) => x.length);
  const out = [];
  let buf = "";

  const flush = () => {
    const t = buf.trim();
    if (!t) return;
    if (phonemeTokenCount(t) <= hardMax) {
      out.push(t);
      buf = "";
      return;
    }
    // Hard split on spaces / stress-group boundaries
    let rest = t;
    while (phonemeTokenCount(rest) > hardMax) {
      const chars = [...rest];
      let takeN = hardMax;
      const slice = chars.slice(0, hardMax).join("");
      const sp = slice.lastIndexOf(" ");
      if (sp > Math.floor(hardMax * 0.4)) takeN = [...slice.slice(0, sp)].length;
      const take = chars.slice(0, takeN).join("").trim();
      if (!take) break;
      out.push(take);
      rest = chars.slice(takeN).join("").trim();
    }
    buf = rest;
  };

  for (const part of parts) {
    const trial = buf + part;
    if (phonemeTokenCount(trial) > targetMax && buf) {
      flush();
      buf = part;
      if (phonemeTokenCount(buf) > hardMax) flush();
    } else if (phonemeTokenCount(trial) > hardMax && buf) {
      flush();
      buf = part;
      if (phonemeTokenCount(buf) > hardMax) flush();
    } else {
      buf = trial;
    }
  }
  if (buf.trim()) flush();
  if (buf.trim()) out.push(buf.trim());

  return out.map(normalizePhonemePunct).filter(Boolean);
}



