const PHONEME_OVERRIDES = {};

function esc(s) {
  return s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

/**
 * Apply lexicon before acronyms/romaji.
 * IPA → ⟦L#⟧ phoneme placeholder.
 * Respellings → ⟦S#⟧ text placeholder (avoids acronym rules eating "SAH"/"KEE").
 */
export function applyLexicon(text, ipaPlaceholders, startIndex = 0) {
  const keys = Object.keys(LEXICON).sort((a, b) => b.length - a.length);
  if (!keys.length) return { text, nextIndex: startIndex };
  let n = startIndex;
  let s = String(text);
  // Optional 's / s on ALLCAPS acronym keys so METI's / IPOs hit the base entry.
  // Do not peel "es" (US+es would steal "USES") or bare "s" from Title names.
  const re = new RegExp(
    `\\b(?:${keys.map(esc).join("|")})(?:['’]s|s)?\\b`,
    "g"
  );
  s = s.replace(re, (m) => {
    let suffix = null;
    let base = m;
    const possessive = m.match(/^(.+)(['’]s)$/);
    if (possessive && !LEXICON[m]) {
      const cand = possessive[1];
      if (Object.keys(LEXICON).some((k) => k.toLowerCase() === cand.toLowerCase())) {
        base = cand;
        suffix = possessive[2];
      }
    }
    const sm = m.match(/^([A-Z]{2,}(?:&[A-Z]+)?)(['’]s|s)$/);
    if (
      sm &&
      !LEXICON[m] &&
      !LEXICON[Object.keys(LEXICON).find((k) => k.toLowerCase() === m.toLowerCase())]
    ) {
      const cand = sm[1];
      const hit =
        LEXICON[cand] ??
        LEXICON[Object.keys(LEXICON).find((k) => k.toLowerCase() === cand.toLowerCase())];
      // Possessive always; plural -s only when base looks like a short acronym key.
      const pluralOk =
        sm[2] === "s" &&
        /^[A-Z]{2,5}$/.test(cand) &&
        (cand === "IPO" || cand === "SME" || cand === "US" || cand === "METI" || hit != null);
      const possOk = sm[2] === "'s" || sm[2] === "’s";
      if (hit != null && (possOk || pluralOk)) {
        base = cand;
        suffix = sm[2];
      }
    }
    const val =
      LEXICON[base] ??
      LEXICON[Object.keys(LEXICON).find((k) => k.toLowerCase() === base.toLowerCase())];
    if (val == null) return m;
    if (PHONEME_OVERRIDES[base] || PHONEME_OVERRIDES[m] || looksLikeIpa(val)) {
      let ipa = sanitizeIpa(PHONEME_OVERRIDES[base] || PHONEME_OVERRIDES[m] || val);
      if (suffix) ipa = `${ipa}z`;
      const key = `⟦L${n++}⟧`;
      ipaPlaceholders.set(key, { kind: "ipa", value: ipa });
      return key;
    }
    const key = `⟦S${n++}⟧`;
    let textVal = String(val);
    if (suffix === "'s" || suffix === "’s") textVal = `${textVal}'s`;
    else if (suffix) textVal = `${textVal}${suffix}`;
    ipaPlaceholders.set(key, { kind: "text", value: textVal });
    return key;
  });
  return { text: s, nextIndex: n };
}

const STRESS_BEFORE_ONSET = /([ˈˌ])([^aeiouæɑɐɒɔəɛɜɪʊʌᵻɚɝ\sˈˌ]+)(?=[aeiouæɑɐɒɔəɛɜɪʊʌᵻɚɝ])/gu;

function placeholderValue(ipaPlaceholders, key) {
  const v = ipaPlaceholders.get(key);
  if (v == null) return { kind: "ipa", value: "" };
  if (typeof v === "string") return { kind: "ipa", value: v };
  return v;
}

/**
 * Phonemize a text segment that may contain ⟦A|R|L|S#⟧ placeholders.
 */
async function phonemizeWithPlaceholders(segment, ipaPlaceholders) {
  const parts = [];
  const re = /⟦[ARLS]\d+⟧/g;
  let last = 0;
  let m;
  const str = String(segment);
  while ((m = re.exec(str)) !== null) {
    if (m.index > last) {
      const piece = str.slice(last, m.index);
      if (piece) parts.push({ type: "text", value: piece });
    }
    const ph = placeholderValue(ipaPlaceholders, m[0]);
    if (ph.kind === "text") parts.push({ type: "text", value: ph.value });
    else parts.push({ type: "ipa", value: ph.value });
    last = m.index + m[0].length;
  }
  if (last < str.length) parts.push({ type: "text", value: str.slice(last) });

  const out = [];
  for (const p of parts) {
    if (p.type === "ipa") {
      if (p.value) {
        // Strip leading secondary stress / schwa / glottal only (keep ˈ on spellings).
        // Leading ˌ before a consonant made Kokoro prepend a vowel (ˌn…→An…).
        let v = String(p.value).replace(/^[ˌəɐʔ]+/, "");
        // Stress must sit before the vowel nucleus, never before an onset
        // consonant ("ˈpiː" made Kokoro say "IAPO"; espeak writes "pˈiː").
        v = v.replace(STRESS_BEFORE_ONSET, "$2$1");
        out.push(v);
      }
    } else {
      const ph = await phonemize(p.value, "a", false);
      if (ph) out.push(ph);
    }
  }
  // Space between espeak and injected IPA prevents joining vowels across boundaries.
  // Then match kokoro-js punctuation spacing (no space around ,;:.!?()) and collapse ",,".
  return normalizePhonemePunct(out.join(" ").replace(/\s+/g, " ").trim());
}

/**
 * @param {string} text
 * @returns {Promise<Array<{ phonemes: string }>>}
 */
export async function prepare(text) {
  const ipaPlaceholders = new Map();
  let s = normalize(text);

  const lex = applyLexicon(s, ipaPlaceholders, 0);
  s = lex.text;

  // espeak treats remaining internal capitals as a word break
  // (OpenAI → "Open AI"). Present CamelCase possessives as one lexical word.
  s = s.replace(/\b([A-Za-z]+(?:[A-Z][a-z]+)+)(['’]s)\b/g, (_, base, suffix) =>
    `${base.toLowerCase()}${suffix}`,
  );

  // normalize() intentionally keeps domain spelling for callers that inspect
  // it; speech should say the separator rather than pause at a literal dot.
  s = s.replace(/\b([A-Za-z0-9-]+(?:\.[A-Za-z0-9-]+)+)\b/g, (_, domain) =>
    domain.replace(/\./g, " dot "),
  );

  const ac = applyAcronyms(s, { ipaPlaceholders, startIndex: 0 });
  s = ac.text;

  const rj = applyRomaji(s, { ipaPlaceholders, startIndex: 0 });
  s = rj.text;

  const textChunks = chunkText(s);
  const rawPieces = [];

  for (const chunk of textChunks) {
    const phon = await phonemizeWithPlaceholders(chunk, ipaPlaceholders);
    if (!phon) continue;
    for (const piece of chunkPhonemes(phon)) {
      rawPieces.push(piece);
    }
  }

  // Pack short phoneme pieces up toward CHUNK_TARGET_MAX without exceeding HARD_MAX.
  // Join with a space so word phonemes do not glue (ˈaɪ+ænd → ˈaɪænd); punct
  // normalize then strips spaces around ,;:.!?() to match kokoro-js.
  const packed = [];
  let buf = "";
  for (const piece of rawPieces) {
    const trial = buf ? normalizePhonemePunct(`${buf} ${piece}`) : piece;
    if (
      buf &&
      (phonemeTokenCount(trial) > CHUNK_TARGET_MAX ||
        phonemeTokenCount(trial) > CHUNK_HARD_MAX)
    ) {
      packed.push(buf);
      buf = piece;
    } else {
      buf = trial;
    }
  }
  if (buf) packed.push(buf);

  const out = [];
  for (const piece of packed) {
    for (const part of chunkPhonemes(piece)) {
      assertPhonemeLimit(part);
      if (phonemeTokenCount(part) > CHUNK_HARD_MAX) {
        throw new Error(
          `chunk exceeds hard max: ${phonemeTokenCount(part)} > ${CHUNK_HARD_MAX}`,
        );
      }
      out.push({ phonemes: part });
    }
  }

  if (!out.length && String(text || "").trim()) {
    const phon = await phonemize(normalize(text), "a", false);
    if (phon) {
      assertPhonemeLimit(phon);
      out.push({ phonemes: phon });
    }
  }
  return out;
}

/** Identity prepare for baseline runs (text chunks; not phoneme contract). */
export function prepareIdentity(text) {
  const s = String(text).trim();
  return s ? [{ text: s }] : [];
}

export {
  normalize,
  numberToWords,
  decimalToWords,
  ordinalToWords,
  applyAcronyms,
  applyRomaji,
  phonemize,
  chunkText,
  chunkPhonemes,
  normalizePhonemePunct,
  CHUNK_HARD_MAX,
  phonemeTokenCount,
  LEXICON,
};

export default prepare;
